let state=await restoreSession(),panel='assistant',mode='resume',zoom=.85,filter='all',search='',saveState='saving',docs=[],saveTimer,previewTimer,toastTimer,undo=[],redo=[],lastHistory=0,storageDetail='',assistantMessages=[],assistantDocumentId=state.id,translationBusy=false,aiEnabled=false,aiConsent=false,aiBusy=false,workspaceTheme='dark',localContext={pending:null};
