function toast(message){const el=$('#toast');if(!el)return;el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),7000);}
function status(){const el=$('#save-status');if(!el)return;el.dataset.state=saveState;el.textContent=saveState==='saved'?tr('Salvo nesta sessão','Saved for this session'):saveState==='saving'?tr('Salvando…','Saving…'):tr('Salvamento indisponível — baixe backup','Saving unavailable — download backup');el.title=storageDetail==='session'?tr('Temporário: baixe antes de fechar a aba.','Temporary: download before closing the tab.'):storageDetail==='memory'?tr('Somente na memória: baixe antes de recarregar.','Memory only: download before reloading.'):storageDetail;}
async function persist(){try{const result=await saveDocument(state);saveState='saved';storageDetail=result.local?'session':'memory';}catch(error){saveState='error';storageDetail=error.message;}status();}
function checkpoint(){if(Date.now()-lastHistory>800){undo.push(structuredClone(state));if(undo.length>30)undo.shift();redo=[];lastHistory=Date.now();}}
function change(mutate,refresh=false){checkpoint();mutate(state);state.updatedAt=Date.now();saveState='saving';try{writeImmediate(state);}catch{}status();clearTimeout(saveTimer);saveTimer=setTimeout(persist,350);if(refresh)renderPanel();schedulePreview();updateToolbar();}
function schedulePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(preview,350);}
function capture(){try{writeImmediate(state);}catch{}void saveDocument(state).catch(()=>{});}
window.addEventListener('pagehide',capture);window.addEventListener('beforeunload',capture);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')capture();});
window.addEventListener('vite:preloadError',event=>{event.preventDefault();$('#update-dialog').showModal();});
function field(key,label,type='text',value=state[key]){return `<label class="field">${label}<input type="${type}" data-field="${key}" value="${e(value)}" maxlength="2000"></label>`;}
function textarea(key,title,rows=5,value=state[state.lang][key]){return `<label class="field">${title}<textarea data-field="${key}" rows="${rows}" maxlength="100000" placeholder="${tr('Escreva aqui. Use uma linha por item.','Write here. Use one line per item.')}">${e(value)}</textarea></label>`;}
