function miniTemplate(t){return `<span class="mini-document ${t.id} layout-${t.layout} header-${t.header}" style="--mini-accent:${state.accent}"><span class="mini-header"><b>${tr('Alex Silva','Alex Morgan')}</b><i>${tr('PERFIL PROFISSIONAL','PROFESSIONAL PROFILE')}</i></span><span class="mini-body"><span><b></b><i></i><i></i><i></i><b></b><i></i><i></i><i></i><b></b><i></i><i></i></span><span><b></b><i></i><i></i><i></i><b></b><i></i><i></i><i></i></span></span></span>`;}
function heading(title,description){return `<div class="panel-heading"><h2>${title}</h2><p>${description}</p></div>`;}
